CHANGELOG = '## [0.237.0] - the backdrop\'s ground is a frame round the plate, never a lid on a basement\n\n**The walker\'s walk of cold run 9383** (the factory\'s `docs/findings/walk_2026-10-23_deli/`, finding 1), of the stair\nopening onto deli_a03\'s basement: "this shouldn\'t look pitch black". 0.211.0 laid one dark unshaded plane under the\nwhole backdrop at `GROUND_Y` (-0.10), "so the plate covers it wherever both stand". The plate does; a building\'s ground\nslab does not, where it has a hole -- a stair, a ladder, a broken floor -- down into a basement: there the plane, a\ntenth of a metre down inside the slab, showed as a black lid at floor level. Measured on cold run 9384\'s walk copy:\nthe ground floor\'s ladder hole read luma 0 through its rim with a lamp lit beside it below, black even under the\ninspection light; with this plane alone hidden, the ladder and the lit basement floor. Every level since 0.211.0 with\na basement under an opening had it.\n\n### Fixed\n- **`with_ground(text, orders, keep_out=)`** lays the ground round `keep_out`, never across it: `ground_strips`, the\n  four strips of the old extent outside it -- south and north the full width, west and east between -- each a unit\n  quad scaled into place in ONE MultiMesh, so still one draw. The extent reaches `GROUND_MARGIN` past `keep_out` too\n  when the plate is wider than the pieces. The report carries `keep_out` and `strips`.\n- **`plate_bound(drawn)`**: the declared plate (`ground.size_x`/`size_y`, at `ground.at` or centred on the origin)\n  and every building\'s footprint, quarter-turns swapping its axes and any other turn bounded by its box, as Lot\'s\n  `site_extent.rotated_footprint` turns them. Lot grows its plate to cover both and never shrinks it, so the frame\'s\n  inner edge is always under the plate. `ship_backdrop` passes it.\n- Priced on cold run 9384\'s walk copy with the frame laid from its own drawn spec against the plate as shipped, the\n  same eleven stations, one session, with the shipped package shot twice for a control: over the east and south\n  fences, at the overview, the elevations, the street stations, p50 and mean identical on every arm; GPU time moves\n  inside what the unchanged package moves between two shots (the control: elev_W -1.71 ms, ladder4 -0.46, elev_N\n  +0.39), so no cost is measurable, and the ground is one object either way. The ladder hole\'s frame mean 45.3 to\n  51.9, the ladder and the lit basement floor where there was black (the factory\'s `patches/lf_backdrop_frame/`).\n\n### Tests\n- `tests/unit/test_backdrop_ground.py`: THE TEST THAT MATTERS -- no strip stands under the plate or any building,\n  deli_a03\'s ground-floor ladder hole among them, and together the strips are all the ground there was less the\n  plate; `plate_bound` reads the plate and turns a building as Lot does; the ground reaches past a plate wider than\n  its pieces; without a plate it is one quad over the old extent; the scene\'s three resources and its\n  MultiMeshInstance3D; the package passes `plate_bound`. On 0.236.1 six of the seven fail; the seventh, that the\n  ground takes no light, holds on both.\n- `tests/unit/test_backdrop_layer.py` counted every MultiMeshInstance3D in the scene as a module\'s: nine. The ground\'s\n  is the tenth, and the test names it. The first apply of this change ran the suite into exactly that one failure.\n\n'
OLD_VERSION, NEW_VERSION = '0.236.1', '0.237.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (LF / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: level_factory/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: level_factory/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: level_factory/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (LF / name).exists():
            raise SystemExit("REFUSED: level_factory/%s exists already; nothing written" % name)
    v = LF / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = LF / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Level Factory %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in level_factory/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
